#!/usr/bin/env python3
"""Convert a Claude Code exported conversation to styled HTML."""

import re
import sys
import html

def parse_conversation(text: str) -> list[dict]:
    """Parse the exported text into a list of message blocks."""
    messages = []
    lines = text.split('\n')
    i = 0

    # Skip header (logo + version info)
    while i < len(lines) and not lines[i].startswith('❯'):
        i += 1

    current = None

    while i < len(lines):
        line = lines[i]

        # User message starts with ❯
        if line.startswith('❯'):
            if current:
                messages.append(current)
            content = line[2:].strip()
            # Collect continuation lines (indented user input)
            i += 1
            while i < len(lines) and lines[i].startswith('  ') and not lines[i].startswith('● ') and not lines[i].startswith('❯') and not lines[i].startswith('✻'):
                extra = lines[i].strip()
                if extra and not extra.startswith('⎿'):
                    content += ' ' + extra
                elif extra.startswith('⎿'):
                    # Inline command output under ❯ — skip
                    pass
                i += 1
            current = {'role': 'user', 'content': content.strip()}
            messages.append(current)
            current = None
            continue

        # Assistant message starts with ●
        if line.startswith('● '):
            if current:
                messages.append(current)

            text_content = line[2:].strip()

            # Check if this is a tool call
            tool_match = re.match(r'^(Bash|Read|Write|Edit|Glob|Grep|Fetch|Explore|Skill|Agent)\(', text_content)
            if tool_match:
                tool_name = tool_match.group(1)
                # Collect tool output lines
                tool_lines = [text_content]
                i += 1
                while i < len(lines) and lines[i].startswith('  ⎿'):
                    tool_lines.append(lines[i].strip())
                    i += 1
                current = {'role': 'tool', 'tool': tool_name, 'content': '\n'.join(tool_lines)}
                messages.append(current)
                current = None
                continue

            # Check for collapsed tool output
            if text_content.startswith('Read ') and 'file' in text_content and '(ctrl+o' in text_content:
                i += 1
                current = None
                continue

            # Check for "User answered" block
            if text_content.startswith('User answered'):
                answer_lines = [text_content]
                i += 1
                while i < len(lines) and lines[i].startswith('  ⎿'):
                    answer_lines.append(lines[i][4:].strip())
                    i += 1
                current = {'role': 'user-answer', 'content': '\n'.join(answer_lines)}
                messages.append(current)
                current = None
                continue

            # Check for hook output
            if text_content.startswith('Ran ') and 'hook' in text_content:
                i += 1
                while i < len(lines) and lines[i].startswith('  ⎿'):
                    i += 1
                current = None
                continue

            # Regular assistant text
            i += 1
            content_lines = [text_content]
            while i < len(lines):
                if lines[i].startswith('❯') or lines[i].startswith('● ') or lines[i].startswith('✻'):
                    break
                content_lines.append(lines[i])
                i += 1
            current = {'role': 'assistant', 'content': '\n'.join(content_lines).strip()}
            continue

        # Timing line
        if line.startswith('✻'):
            if current:
                messages.append(current)
                current = None
            i += 1
            continue

        i += 1

    if current:
        messages.append(current)

    return messages


def render_markdown_basic(text: str) -> str:
    """Basic markdown to HTML conversion."""
    text = html.escape(text)

    # Code blocks (``` ... ```)
    def replace_code_block(m):
        lang = m.group(1) or ''
        code = m.group(2).strip()
        return f'<pre><code class="language-{lang}">{code}</code></pre>'
    text = re.sub(r'```(\w*)\n(.*?)```', replace_code_block, text, flags=re.DOTALL)

    # Inline code
    text = re.sub(r'`([^`]+)`', r'<code>\1</code>', text)

    # Bold
    text = re.sub(r'\*\*(.+?)\*\*', r'<strong>\1</strong>', text)

    # Headers
    text = re.sub(r'^### (.+)$', r'<h4>\1</h4>', text, flags=re.MULTILINE)
    text = re.sub(r'^## (.+)$', r'<h3>\1</h3>', text, flags=re.MULTILINE)
    text = re.sub(r'^# (.+)$', r'<h2>\1</h2>', text, flags=re.MULTILINE)

    # Lists - handle numbered and bulleted
    text = re.sub(r'^(\d+)\. (.+)$', r'<li>\2</li>', text, flags=re.MULTILINE)
    text = re.sub(r'^- (.+)$', r'<li>\1</li>', text, flags=re.MULTILINE)

    # Wrap consecutive <li> in <ul>/<ol>
    text = re.sub(r'((?:<li>.*?</li>\n?)+)', r'<ul>\1</ul>', text)

    # Paragraphs - wrap non-tag lines
    lines = text.split('\n')
    result = []
    in_pre = False
    para_lines = []

    def flush_para():
        if para_lines:
            content = ' '.join(para_lines).strip()
            if content:
                result.append(f'<p>{content}</p>')
            para_lines.clear()

    for line in lines:
        if '<pre>' in line:
            in_pre = True
        if '</pre>' in line:
            in_pre = False
        if in_pre:
            flush_para()
            result.append(line)
            continue
        if line.strip() == '':
            flush_para()
        elif line.strip().startswith('<h') or line.strip().startswith('<ul') or line.strip().startswith('<ol') or line.strip().startswith('<pre'):
            flush_para()
            result.append(line)
        else:
            para_lines.append(line.strip())

    flush_para()
    return '\n'.join(result)


def messages_to_html(messages: list[dict]) -> str:
    """Convert parsed messages to HTML."""
    blocks = []

    for msg in messages:
        role = msg['role']
        content = msg['content']

        if role == 'user':
            blocks.append(f'''
            <div class="message user-message">
                <div class="message-role">You</div>
                <div class="message-content">{render_markdown_basic(content)}</div>
            </div>''')

        elif role == 'assistant':
            blocks.append(f'''
            <div class="message assistant-message">
                <div class="message-role">Claude</div>
                <div class="message-content">{render_markdown_basic(content)}</div>
            </div>''')

        elif role == 'tool':
            tool = msg.get('tool', 'Tool')
            blocks.append(f'''
            <div class="message tool-message">
                <div class="tool-header" onclick="this.parentElement.classList.toggle('expanded')">
                    <span class="tool-icon">&#9656;</span> {html.escape(tool)}
                </div>
                <div class="tool-content"><pre>{html.escape(content)}</pre></div>
            </div>''')

        elif role == 'user-answer':
            blocks.append(f'''
            <div class="message user-answer-message">
                <div class="message-role">Your Answers</div>
                <div class="message-content"><pre>{html.escape(content)}</pre></div>
            </div>''')

    return '\n'.join(blocks)


def build_html(messages: list[dict]) -> str:
    """Build the full HTML page."""
    body = messages_to_html(messages)

    return f'''<!DOCTYPE html>
