#!/usr/bin/env python3
"""Convert a Claude Code exported conversation to styled HTML."""

import re
import sys
import html

def parse_conversation(text: str) -> list[dict]:
    """Parse the exported text into a list of message blocks."""
    messages = []
    lines = text.split('\n')
    i = 0

    # Skip header (logo + version info)
    while i < len(lines) and not lines[i].startswith('❯'):
        i += 1

    current = None

    while i < len(lines):
        line = lines[i]

        # User message starts with ❯
        if line.startswith('❯'):
            if current:
                messages.append(current)
            content = line[2:].strip()
            # Collect continuation lines (indented user input)
            i += 1
            while i < len(lines) and lines[i].startswith('  ') and not lines[i].startswith('● ') and not lines[i].startswith('❯') and not lines[i].startswith('✻'):
                extra = lines[i].strip()
                if extra and not extra.startswith('⎿'):
                    content += ' ' + extra
                elif extra.startswith('⎿'):
                    # Inline command output under ❯ — skip
                    pass
                i += 1
            current = {'role': 'user', 'content': content.strip()}
            messages.append(current)
            current = None
            continue

        # Assistant message starts with ●
        if line.startswith('● '):
            if current:
                messages.append(current)

            text_content = line[2:].strip()

            # Check if this is a tool call
            tool_match = re.match(r'^(Bash|Read|Write|Edit|Glob|Grep|Fetch|Explore|Skill|Agent)\(', text_content)
            if tool_match:
                tool_name = tool_match.group(1)
                # Collect tool output lines
                tool_lines = [text_content]
                i += 1
                while i < len(lines) and lines[i].startswith('  ⎿'):
                    tool_lines.append(lines[i].strip())
                    i += 1
                current = {'role': 'tool', 'tool': tool_name, 'content': '\n'.join(tool_lines)}
                messages.append(current)
                current = None
                continue

            # Check for collapsed tool output
            if text_content.startswith('Read ') and 'file' in text_content and '(ctrl+o' in text_content:
                i += 1
                current = None
                continue

            # Check for "User answered" block
            if text_content.startswith('User answered'):
                answer_lines = [text_content]
                i += 1
                while i < len(lines) and lines[i].startswith('  ⎿'):
                    answer_lines.append(lines[i][4:].strip())
                    i += 1
                current = {'role': 'user-answer', 'content': '\n'.join(answer_lines)}
                messages.append(current)
                current = None
                continue

            # Check for hook output
            if text_content.startswith('Ran ') and 'hook' in text_content:
                i += 1
                while i < len(lines) and lines[i].startswith('  ⎿'):
                    i += 1
                current = None
                continue

            # Regular assistant text
            i += 1
            content_lines = [text_content]
            while i < len(lines):
                if lines[i].startswith('❯') or lines[i].startswith('● ') or lines[i].startswith('✻'):
                    break
                content_lines.append(lines[i])
                i += 1
            current = {'role': 'assistant', 'content': '\n'.join(content_lines).strip()}
            continue

        # Timing line
        if line.startswith('✻'):
            if current:
                messages.append(current)
                current = None
            i += 1
            continue

        i += 1

    if current:
        messages.append(current)

    return messages


def render_markdown_basic(text: str) -> str:
    """Basic markdown to HTML conversion."""
    text = html.escape(text)

    # Code blocks (``` ... ```)
    def replace_code_block(m):
        lang = m.group(1) or ''
        code = m.group(2).strip()
        return f'<pre><code class="language-{lang}">{code}</code></pre>'
    text = re.sub(r'```(\w*)\n(.*?)```', replace_code_block, text, flags=re.DOTALL)

    # Inline code
    text = re.sub(r'`([^`]+)`', r'<code>\1</code>', text)

    # Bold
    text = re.sub(r'\*\*(.+?)\*\*', r'<strong>\1</strong>', text)

    # Headers
    text = re.sub(r'^### (.+)$', r'<h4>\1</h4>', text, flags=re.MULTILINE)
    text = re.sub(r'^## (.+)$', r'<h3>\1</h3>', text, flags=re.MULTILINE)
    text = re.sub(r'^# (.+)$', r'<h2>\1</h2>', text, flags=re.MULTILINE)

    # Lists - handle numbered and bulleted
    text = re.sub(r'^(\d+)\. (.+)$', r'<li>\2</li>', text, flags=re.MULTILINE)
    text = re.sub(r'^- (.+)$', r'<li>\1</li>', text, flags=re.MULTILINE)

    # Wrap consecutive <li> in <ul>/<ol>
    text = re.sub(r'((?:<li>.*?</li>\n?)+)', r'<ul>\1</ul>', text)

    # Paragraphs - wrap non-tag lines
    lines = text.split('\n')
    result = []
    in_pre = False
    para_lines = []

    def flush_para():
        if para_lines:
            content = ' '.join(para_lines).strip()
            if content:
                result.append(f'<p>{content}</p>')
            para_lines.clear()

    for line in lines:
        if '<pre>' in line:
            in_pre = True
        if '</pre>' in line:
            in_pre = False
        if in_pre:
            flush_para()
            result.append(line)
            continue
        if line.strip() == '':
            flush_para()
        elif line.strip().startswith('<h') or line.strip().startswith('<ul') or line.strip().startswith('<ol') or line.strip().startswith('<pre'):
            flush_para()
            result.append(line)
        else:
            para_lines.append(line.strip())

    flush_para()
    return '\n'.join(result)


def messages_to_html(messages: list[dict]) -> str:
    """Convert parsed messages to HTML."""
    blocks = []

    for msg in messages:
        role = msg['role']
        content = msg['content']

        if role == 'user':
            blocks.append(f'''
            <div class="message user-message">
                <div class="message-role">You</div>
                <div class="message-content">{render_markdown_basic(content)}</div>
            </div>''')

        elif role == 'assistant':
            blocks.append(f'''
            <div class="message assistant-message">
                <div class="message-role">Claude</div>
                <div class="message-content">{render_markdown_basic(content)}</div>
            </div>''')

        elif role == 'tool':
            tool = msg.get('tool', 'Tool')
            blocks.append(f'''
            <div class="message tool-message">
                <div class="tool-header" onclick="this.parentElement.classList.toggle('expanded')">
                    <span class="tool-icon">&#9656;</span> {html.escape(tool)}
                </div>
                <div class="tool-content"><pre>{html.escape(content)}</pre></div>
            </div>''')

        elif role == 'user-answer':
            blocks.append(f'''
            <div class="message user-answer-message">
                <div class="message-role">Your Answers</div>
                <div class="message-content"><pre>{html.escape(content)}</pre></div>
            </div>''')

    return '\n'.join(blocks)


def build_html(messages: list[dict]) -> str:
    """Build the full HTML page."""
    body = messages_to_html(messages)

    return f'''<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Claude Code Conversation</title>
<style>
    :root {{
        --bg-primary: #2b2a27;
        --bg-secondary: #353431;
        --bg-user: #3d3b36;
        --bg-tool: #2f2e2b;
        --text-primary: #e8e4dc;
        --text-secondary: #a8a49c;
        --text-muted: #7a776f;
        --accent: #d4a574;
        --accent-dim: #a67c52;
        --border: #454340;
        --code-bg: #232220;
        --user-label: #c4956a;
        --claude-label: #d4a574;
    }}

    * {{
        margin: 0;
        padding: 0;
        box-sizing: border-box;
    }}

    body {{
        background: var(--bg-primary);
        color: var(--text-primary);
        font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, 'Helvetica Neue', Arial, sans-serif;
        font-size: 15px;
        line-height: 1.6;
        max-width: 820px;
        margin: 0 auto;
        padding: 40px 20px;
    }}

    .message {{
        margin-bottom: 28px;
        padding: 0;
    }}

    .message-role {{
        font-size: 13px;
        font-weight: 600;
        margin-bottom: 6px;
        letter-spacing: 0.02em;
    }}

    .user-message .message-role {{
        color: var(--user-label);
    }}

    .assistant-message .message-role {{
        color: var(--claude-label);
    }}

    .user-message .message-content {{
        background: var(--bg-user);
        border-radius: 12px;
        padding: 14px 18px;
    }}

    .assistant-message .message-content {{
        padding: 4px 0;
    }}

    .message-content p {{
        margin-bottom: 12px;
    }}

    .message-content p:last-child {{
        margin-bottom: 0;
    }}

    .message-content h2 {{
        font-size: 18px;
        margin: 20px 0 10px 0;
        color: var(--text-primary);
    }}

    .message-content h3 {{
        font-size: 16px;
        margin: 16px 0 8px 0;
        color: var(--text-primary);
    }}

    .message-content h4 {{
        font-size: 15px;
        margin: 14px 0 6px 0;
        color: var(--text-primary);
    }}

    .message-content ul, .message-content ol {{
        padding-left: 24px;
        margin-bottom: 12px;
    }}

    .message-content li {{
        margin-bottom: 4px;
    }}

    .message-content code {{
        background: var(--code-bg);
        padding: 2px 6px;
        border-radius: 4px;
        font-family: 'SF Mono', 'Fira Code', 'Cascadia Code', 'JetBrains Mono', monospace;
        font-size: 13px;
        color: var(--accent);
    }}

    .message-content pre {{
        background: var(--code-bg);
        border-radius: 8px;
        padding: 14px 16px;
        overflow-x: auto;
        margin-bottom: 12px;
        border: 1px solid var(--border);
    }}

    .message-content pre code {{
        background: none;
        padding: 0;
        color: var(--text-primary);
        font-size: 13px;
        line-height: 1.5;
    }}

    .message-content strong {{
        color: var(--text-primary);
        font-weight: 600;
    }}

    .message-content table {{
        border-collapse: collapse;
        margin-bottom: 12px;
        width: 100%;
    }}

    .message-content th, .message-content td {{
        border: 1px solid var(--border);
        padding: 8px 12px;
        text-align: left;
    }}

    .message-content th {{
        background: var(--bg-secondary);
        font-weight: 600;
    }}

    /* Tool calls */
    .tool-message {{
        margin-bottom: 16px;
    }}

    .tool-header {{
        display: flex;
        align-items: center;
        gap: 6px;
        padding: 8px 12px;
        background: var(--bg-tool);
        border: 1px solid var(--border);
        border-radius: 8px;
        cursor: pointer;
        font-family: 'SF Mono', 'Fira Code', monospace;
        font-size: 13px;
        color: var(--text-secondary);
        user-select: none;
    }}

    .tool-header:hover {{
        background: var(--bg-secondary);
    }}

    .tool-icon {{
        font-size: 10px;
        transition: transform 0.15s;
    }}

    .tool-message.expanded .tool-icon {{
        transform: rotate(90deg);
    }}

    .tool-content {{
        display: none;
        margin-top: 4px;
        border-left: 2px solid var(--border);
        margin-left: 8px;
    }}

    .tool-message.expanded .tool-content {{
        display: block;
    }}

    .tool-content pre {{
        background: var(--code-bg);
        border-radius: 0 8px 8px 8px;
        padding: 12px 14px;
        overflow-x: auto;
        font-size: 12px;
        color: var(--text-secondary);
        line-height: 1.5;
        margin: 0;
        border: none;
    }}

    /* User answer blocks */
    .user-answer-message .message-role {{
        color: var(--user-label);
    }}

    .user-answer-message .message-content {{
        background: var(--bg-user);
        border-radius: 12px;
        padding: 14px 18px;
    }}

    .user-answer-message pre {{
        background: transparent;
        border: none;
        padding: 0;
        margin: 0;
        font-family: inherit;
        font-size: inherit;
        color: inherit;
        white-space: pre-wrap;
        word-wrap: break-word;
    }}

    /* Scrollbar */
    ::-webkit-scrollbar {{
        width: 6px;
        height: 6px;
    }}
    ::-webkit-scrollbar-track {{
        background: transparent;
    }}
    ::-webkit-scrollbar-thumb {{
        background: var(--border);
        border-radius: 3px;
    }}
</style>
</head>
<body>
    <div class="conversation">
        {body}
    </div>
</body>
</html>'''


if __name__ == '__main__':
    input_path = sys.argv[1] if len(sys.argv) > 1 else '/workspace/2026-03-02-053053-do-you-have-a-skill-for-creating-skills.txt'
    output_path = sys.argv[2] if len(sys.argv) > 2 else input_path.rsplit('.', 1)[0] + '.html'

    with open(input_path) as f:
        text = f.read()

    messages = parse_conversation(text)
    html_content = build_html(messages)

    with open(output_path, 'w') as f:
        f.write(html_content)

    print(f"Wrote {output_path} ({len(messages)} messages)")
